const chargedGolemSheet=new Image();chargedGolemSheet.assetSrc='assets/charged-golem-v1.png';let chargedPullClock=-Infinity,chargedPullUsed=0;
function beginChargedGolem(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'golemMagneticCrush',bespoke:true,windup:1.8,origin:{x:e.x,y:e.y},fired:false};}
function pullChargedGolem(a,span){if(span<=0||p.inv>0)return;let d=dist(a.origin,p);if(d<=70||d>300||!lineClear(a.origin,p))return;if(chargedPullClock!==clock){chargedPullClock=clock;chargedPullUsed=0;}let step=Math.min(d-70,Math.max(0,60*span-chargedPullUsed));if(step<=0)return;chargedPullUsed+=step;moveActor(p,(a.origin.x-p.x)/d*step,(a.origin.y-p.y)/d*step,13);}
const chargedGolemAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r6e4')return chargedGolemAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='golemMagneticCrush'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=280&&clear){beginChargedGolem(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,58*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,26)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;pullChargedGolem(a,Math.max(0,Math.min(e.elapsed,1.4)-Math.max(before,.4)));
 if(!a.fired&&e.elapsed>=1.8){a.fired=true;e.struck=true;if(dist(p,a.origin)<=150+1e-8&&lineClear(a.origin,p))hurt(88);burst(a.origin.x,a.origin.y,150,'#f4d58e');playSound('impact',e.x,e.y);}if(e.elapsed>=3){e.attack=null;e.state='idle';e.t=2.8;}
};
const chargedGolemDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r6e4'||!chargedGolemSheet.complete||!chargedGolemSheet.naturalWidth||!chargedGolemSheet.naturalHeight)return chargedGolemDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='golemMagneticCrush')f={row:2,col:e.elapsed<.4?0:e.elapsed<1.4?1:e.elapsed<1.8?2:3};let q=project(e.x,e.y),sw=chargedGolemSheet.naturalWidth/4,sh=chargedGolemSheet.naturalHeight/3,w=300,h=w*sh/sw,anchor=.87;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,chargedGolemSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(chargedGolemSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const chargedGolemSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r6e4'?195:chargedGolemSizeBase(e);
const chargedGolemGroundBase=drawGroundEffects;drawGroundEffects=()=>{chargedGolemGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e4'):enemies)){let a=e.attack;if(e.species!=='r6e4'||e.hp<=0||a?.pattern!=='golemMagneticCrush'||e.elapsed>=2||!visibleAt(e.x,e.y))continue;groundRing(a.origin.x,a.origin.y,150,a.fired?'#fff0c0':'#efad76',a.fired?3:2);if(e.elapsed<1.4){groundRing(a.origin.x,a.origin.y,300,'#8db1db',1);let r=260-150*Math.max(0,(e.elapsed-.4)% .5)/.5;for(let i=0;i<6;i++){let angle=i*Math.PI/3,q=project(a.origin.x+Math.cos(angle)*r,a.origin.y+Math.sin(angle)*r),end=project(a.origin.x+Math.cos(angle)*(r-22),a.origin.y+Math.sin(angle)*(r-22));ctx.save();ctx.strokeStyle='#a0cbe4';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(end.x,end.y);ctx.stroke();ctx.restore();}}}};
